// AUTO-GENERATED from "Commercial Property Sale Service Agreement - V0.2.txt" (V0.2) by scripts/genSalesAgreementClauses.js.
// Verbatim clause text; do not hand-edit — re-run the generator to refresh.
module.exports = [
  ["PURPOSE", "<p style=\"margin:6px 0;\">This Agreement sets out the terms and conditions under which Seventh Sky will provide Commercial Property Sale Services to assist the Seller in preparing, marketing, negotiating and coordinating the sale of a commercial property.</p><p style=\"margin:6px 0;\">The Agreement establishes the rights and responsibilities of both Parties in relation to property preparation, marketing, buyer management, negotiations, documentation coordination, settlement support and other agreed commercial property sale services.</p><p style=\"margin:6px 0;\">The specific Services, pricing and engagement scope applicable to each property shall be confirmed in the approved Quotation, Work Order or Schedule B.</p>"],
  ["TERM", "<p style=\"margin:6px 0;\">This Agreement becomes effective on the date it is signed by both Parties and continues until:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the property sale is completed;</li><li style=\"margin:2px 0;\">the agreed Services have been completed;</li><li style=\"margin:2px 0;\">this Agreement is terminated in accordance with its terms; or</li><li style=\"margin:2px 0;\">both Parties otherwise agree in writing.</li></ul><p style=\"margin:6px 0;\">Where the Seller engages Seventh Sky on an exclusive basis, the exclusive engagement period shall be specified in the approved Quotation or Work Order.</p>"],
  ["SERVICES", "<p style=\"margin:6px 0;\">Depending on the selected Service Package, Seventh Sky may provide one or more of the following Services.</p><p style=\"margin:6px 0;\">Only the Services selected in Schedule A or the approved Work Order form part of this Agreement.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Property Assessment &amp; Sales Strategy</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Initial Consultation</li><li style=\"margin:2px 0;\">☐ Commercial Property Assessment</li><li style=\"margin:2px 0;\">☐ Market Analysis</li><li style=\"margin:2px 0;\">☐ Pricing Strategy</li><li style=\"margin:2px 0;\">☐ Sales Strategy</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Property Preparation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Cleaning Coordination</li><li style=\"margin:2px 0;\">☐ Repairs &amp; Maintenance Coordination</li><li style=\"margin:2px 0;\">☐ Renovation Coordination</li><li style=\"margin:2px 0;\">☐ Property Presentation Coordination</li><li style=\"margin:2px 0;\">☐ Compliance Preparation Support</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Marketing &amp; Promotion</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Professional Photography Coordination</li><li style=\"margin:2px 0;\">☐ Drone Photography Coordination</li><li style=\"margin:2px 0;\">☐ Commercial Property Listing</li><li style=\"margin:2px 0;\">☐ Online Marketing</li><li style=\"margin:2px 0;\">☐ Social Media Promotion</li><li style=\"margin:2px 0;\">☐ Advertising Campaigns</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Buyer Management</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Buyer Enquiry Management</li><li style=\"margin:2px 0;\">☐ Buyer Qualification</li><li style=\"margin:2px 0;\">☐ Inspection Coordination</li><li style=\"margin:2px 0;\">☐ Offer Coordination</li><li style=\"margin:2px 0;\">☐ Negotiation Support</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Documentation &amp; Settlement</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Ownership Documentation Coordination</li><li style=\"margin:2px 0;\">☐ Sale Documentation Coordination</li><li style=\"margin:2px 0;\">☐ Conveyancing Coordination</li><li style=\"margin:2px 0;\">☐ Settlement Coordination</li><li style=\"margin:2px 0;\">☐ Property Handover Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Additional Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Property Valuation Coordination</li><li style=\"margin:2px 0;\">☐ Engineering Inspection Coordination</li><li style=\"margin:2px 0;\">☐ Survey Coordination</li><li style=\"margin:2px 0;\">☐ Legal Documentation Coordination</li><li style=\"margin:2px 0;\">☐ Business Sale Coordination (If Applicable)</li><li style=\"margin:2px 0;\">☐ Other: _______________________</li></ul><p style=\"margin:6px 0;\">Additional Services may be included by written agreement.</p>"],
  ["PROPERTY DETAILS", "<p style=\"margin:6px 0;\">The property details shall be recorded in Schedule B or the approved Work Order.</p><p style=\"margin:6px 0;\">The information may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Property Address;</li><li style=\"margin:2px 0;\">Property Type;</li><li style=\"margin:2px 0;\">Ownership Status;</li><li style=\"margin:2px 0;\">Current Tenancy (if applicable);</li><li style=\"margin:2px 0;\">Existing Business Use;</li><li style=\"margin:2px 0;\">Estimated Market Value;</li><li style=\"margin:2px 0;\">Agreed Listing Price;</li><li style=\"margin:2px 0;\">Minimum Acceptable Sale Price (if agreed);</li><li style=\"margin:2px 0;\">Selected Services; and</li><li style=\"margin:2px 0;\">Special Conditions.</li></ul><p style=\"margin:6px 0;\">Where any inconsistency exists between this Agreement and the approved Work Order or Schedule B, the approved Work Order or Schedule B shall prevail for that transaction.</p>"],
  ["SELLER RESPONSIBILITIES", "<p style=\"margin:6px 0;\">The Seller agrees to:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide accurate ownership and property information;</li><li style=\"margin:2px 0;\">confirm that they have lawful authority to market and sell the property;</li><li style=\"margin:2px 0;\">provide all documents reasonably required for the sale process;</li><li style=\"margin:2px 0;\">disclose any mortgage, charge, encumbrance, court order, tenancy or other matter affecting the property;</li><li style=\"margin:2px 0;\">cooperate with inspections, marketing activities and buyer enquiries;</li><li style=\"margin:2px 0;\">provide reasonable access to the property;</li><li style=\"margin:2px 0;\">promptly review offers and sale documentation;</li><li style=\"margin:2px 0;\">pay all agreed Professional Service Fees and approved third-party costs;</li><li style=\"margin:2px 0;\">promptly notify Seventh Sky of any material changes affecting the property or sale; and</li><li style=\"margin:2px 0;\">obtain independent legal, taxation and financial advice where appropriate.</li></ul><p style=\"margin:6px 0;\">The Seller remains responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the accuracy of all ownership and property information;</li><li style=\"margin:2px 0;\">legal ownership of the property;</li><li style=\"margin:2px 0;\">taxation obligations arising from the sale;</li><li style=\"margin:2px 0;\">settlement obligations;</li><li style=\"margin:2px 0;\">government charges; and</li><li style=\"margin:2px 0;\">compliance with all applicable laws.</li></ul>"],
  ["RESPONSIBILITIES OF SEVENTH SKY", "<p style=\"margin:6px 0;\">Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide the agreed Services with reasonable care, skill and professional diligence;</li><li style=\"margin:2px 0;\">assist in developing an appropriate sales strategy;</li><li style=\"margin:2px 0;\">coordinate the agreed marketing activities;</li><li style=\"margin:2px 0;\">communicate with prospective buyers and authorised representatives;</li><li style=\"margin:2px 0;\">coordinate inspections and buyer enquiries;</li><li style=\"margin:2px 0;\">assist with negotiations where authorised;</li><li style=\"margin:2px 0;\">coordinate documentation and settlement activities where included within the agreed Services;</li><li style=\"margin:2px 0;\">coordinate communication with approved third-party professionals where authorised;</li><li style=\"margin:2px 0;\">maintain appropriate records relating to the Services; and</li><li style=\"margin:2px 0;\">keep the Seller reasonably informed throughout the engagement.</li></ul><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts solely as a Commercial Property Sale Service Provider and Coordinator and does not become the property owner, purchaser, legal adviser, accountant, valuer, surveyor, engineer, financier or government authority.</p><p style=\"margin:6px 0;\">Seventh Sky shall not execute a Sale Agreement, accept an offer or legally bind the Seller unless expressly authorised in writing by the Seller.</p>"],
  ["QUOTATIONS & WORK ORDERS", "<p style=\"margin:6px 0;\">Before commencing the Services, Seventh Sky may issue a Quotation or Work Order specifying:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the agreed Services;</li><li style=\"margin:2px 0;\">selected Service Package;</li><li style=\"margin:2px 0;\">engagement type (exclusive or non-exclusive);</li><li style=\"margin:2px 0;\">Professional Service Fees;</li><li style=\"margin:2px 0;\">commission or success fee (where applicable);</li><li style=\"margin:2px 0;\">approved third-party costs;</li><li style=\"margin:2px 0;\">payment schedule;</li><li style=\"margin:2px 0;\">expected project timeframe; and</li><li style=\"margin:2px 0;\">any special conditions.</li></ul><p style=\"margin:6px 0;\">Additional Services requested after commencement may require a revised Quotation, Work Order or approved variation before work proceeds.</p>"],
  ["SERVICE FEES & PAYMENT", "<p style=\"margin:6px 0;\">The Professional Service Fees payable under this Agreement shall be specified in the approved Quotation, Work Order or Schedule B.</p><p style=\"margin:6px 0;\">Depending on the selected Service Package, the Service Fees may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Initial Consultation;</li><li style=\"margin:2px 0;\">Commercial Property Assessment;</li><li style=\"margin:2px 0;\">Property Preparation Coordination;</li><li style=\"margin:2px 0;\">Marketing &amp; Promotion;</li><li style=\"margin:2px 0;\">Buyer Management;</li><li style=\"margin:2px 0;\">Inspection Coordination;</li><li style=\"margin:2px 0;\">Negotiation Support;</li><li style=\"margin:2px 0;\">Documentation &amp; Settlement Coordination;</li><li style=\"margin:2px 0;\">Commission or Success Fee (where applicable);</li><li style=\"margin:2px 0;\">Approved Third-Party Costs; and</li><li style=\"margin:2px 0;\">Additional Services requested by the Seller.</li></ul><p style=\"margin:6px 0;\">The Seller agrees to pay all agreed Professional Service Fees in accordance with the approved payment schedule.</p><p style=\"margin:6px 0;\">Government charges, taxes, registration fees, legal expenses, conveyancing fees, mortgage discharge costs, valuation fees, engineering inspection fees, survey fees and other approved third-party expenses remain the responsibility of the Seller unless otherwise agreed in writing.</p>"],
  ["PAYMENT TERMS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Professional Service Fees</p><p style=\"margin:6px 0;\">Professional Service Fees shall be payable in accordance with the approved Quotation, Work Order or Schedule B.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Commission-Based Engagement</p><p style=\"margin:6px 0;\">Where the Parties agree to a commission or success fee arrangement, the agreed commission or success fee becomes payable upon successful completion of the property sale or as otherwise specified in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Invoices are payable within the period stated on the invoice.</p><p style=\"margin:6px 0;\">Late payment may result in suspension of the Services until outstanding amounts have been paid.</p>"],
  ["COMMERCIAL PROPERTY SALE SERVICES", "<p style=\"margin:6px 0;\">Seventh Sky will use reasonable efforts to assist the Seller in marketing and selling the commercial property in accordance with the agreed scope of Services.</p><p style=\"margin:6px 0;\">Depending on the selected Service Package, the Services may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commercial property assessment;</li><li style=\"margin:2px 0;\">pricing strategy guidance;</li><li style=\"margin:2px 0;\">property preparation coordination;</li><li style=\"margin:2px 0;\">marketing and promotion;</li><li style=\"margin:2px 0;\">buyer enquiry management;</li><li style=\"margin:2px 0;\">inspection coordination;</li><li style=\"margin:2px 0;\">negotiation support;</li><li style=\"margin:2px 0;\">documentation coordination;</li><li style=\"margin:2px 0;\">settlement coordination;</li><li style=\"margin:2px 0;\">property handover coordination; and</li><li style=\"margin:2px 0;\">other agreed sale support services.</li></ul><p style=\"margin:6px 0;\">The Seller acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">market conditions may affect the sale price and timeframe;</li><li style=\"margin:2px 0;\">prospective buyers may withdraw or amend their offers;</li><li style=\"margin:2px 0;\">purchaser finance approval is beyond Seventh Sky's control;</li><li style=\"margin:2px 0;\">the successful sale of the property cannot be guaranteed; and</li><li style=\"margin:2px 0;\">the final decision to accept or reject any offer remains with the Seller.</li></ul>"],
  ["PROJECT TIMELINES", "<p style=\"margin:6px 0;\">Estimated commencement and completion dates will be provided in the approved Quotation, Work Order or Schedule B where applicable.</p><p style=\"margin:6px 0;\">Project timeframes may vary depending on factors including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">market conditions;</li><li style=\"margin:2px 0;\">buyer demand;</li><li style=\"margin:2px 0;\">property readiness;</li><li style=\"margin:2px 0;\">inspections;</li><li style=\"margin:2px 0;\">negotiations;</li><li style=\"margin:2px 0;\">legal documentation;</li><li style=\"margin:2px 0;\">finance approval;</li><li style=\"margin:2px 0;\">settlement arrangements;</li><li style=\"margin:2px 0;\">government requirements;</li><li style=\"margin:2px 0;\">public holidays; and</li><li style=\"margin:2px 0;\">other circumstances beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where delays occur, Seventh Sky will keep the Seller reasonably informed and provide revised estimated timeframes where reasonably practicable.</p>"],
  ["VARIATIONS & ADDITIONAL SERVICES", "<p style=\"margin:6px 0;\">The Seller may request changes to the agreed scope of Services at any time.</p><p style=\"margin:6px 0;\">Additional Services may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">additional marketing campaigns;</li><li style=\"margin:2px 0;\">additional inspections;</li><li style=\"margin:2px 0;\">professional photography or drone services;</li><li style=\"margin:2px 0;\">property presentation or styling;</li><li style=\"margin:2px 0;\">extended negotiations;</li><li style=\"margin:2px 0;\">valuation, engineering or survey coordination;</li><li style=\"margin:2px 0;\">legal documentation coordination;</li><li style=\"margin:2px 0;\">business sale coordination; or</li><li style=\"margin:2px 0;\">any other Services requested by the Seller.</li></ul><p style=\"margin:6px 0;\">Where a variation affects the Professional Service Fees, project scope or timeframe, Seventh Sky will provide a revised Quotation, Work Order or variation for approval before proceeding.</p><p style=\"margin:6px 0;\">Immediate action reasonably required to protect the Seller's interests or facilitate the sale process may be undertaken without prior approval where obtaining approval is not reasonably practicable.</p>"],
  ["THIRD-PARTY SERVICES", "<p style=\"margin:6px 0;\">Where required, Seventh Sky may coordinate independent third-party professionals to support the delivery of the agreed Services.</p><p style=\"margin:6px 0;\">These may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">prospective buyers;</li><li style=\"margin:2px 0;\">lawyers and conveyancers;</li><li style=\"margin:2px 0;\">accountants;</li><li style=\"margin:2px 0;\">banks and financial institutions;</li><li style=\"margin:2px 0;\">valuers;</li><li style=\"margin:2px 0;\">surveyors;</li><li style=\"margin:2px 0;\">engineers;</li><li style=\"margin:2px 0;\">contractors;</li><li style=\"margin:2px 0;\">government authorities; and</li><li style=\"margin:2px 0;\">other approved professional service providers.</li></ul><p style=\"margin:6px 0;\">The Seller acknowledges that these providers operate independently and remain responsible for their own advice, reports and professional services.</p><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts solely as the coordinator of these Services and is not responsible for the advice, reports, products or services provided by independent third parties.</p>"],
  ["SERVICE COMPLETION", "<p style=\"margin:6px 0;\">The Services shall be deemed complete when Seventh Sky has substantially delivered the Services specified in the approved Quotation, Work Order or Schedule B.</p><p style=\"margin:6px 0;\">Depending on the agreed scope, completion may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commercial property assessment completed;</li><li style=\"margin:2px 0;\">property preparation coordinated;</li><li style=\"margin:2px 0;\">marketing campaign completed;</li><li style=\"margin:2px 0;\">buyer enquiries managed;</li><li style=\"margin:2px 0;\">inspections coordinated;</li><li style=\"margin:2px 0;\">negotiations completed;</li><li style=\"margin:2px 0;\">sale documentation coordinated;</li><li style=\"margin:2px 0;\">settlement coordination completed;</li><li style=\"margin:2px 0;\">property handover coordinated; or</li><li style=\"margin:2px 0;\">other agreed Services completed.</li></ul><p style=\"margin:6px 0;\">Where Seventh Sky is engaged for ongoing post-sale support, the Services shall continue until the agreed engagement period expires or is terminated in accordance with this Agreement.</p>"],
  ["CLIENT COMPLAINTS", "<p style=\"margin:6px 0;\">If the Seller is dissatisfied with any aspect of the Services, the Seller should notify Seventh Sky as soon as reasonably practicable.</p><p style=\"margin:6px 0;\">Upon receiving a complaint, Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">acknowledge receipt of the complaint;</li><li style=\"margin:2px 0;\">investigate the matter;</li><li style=\"margin:2px 0;\">communicate with the Seller throughout the review process;</li><li style=\"margin:2px 0;\">take reasonable steps to resolve the issue where appropriate; and</li><li style=\"margin:2px 0;\">advise the Seller of the outcome.</li></ul><p style=\"margin:6px 0;\">Where a complaint relates to a prospective buyer or an independent third-party service provider, Seventh Sky will assist in facilitating communication where reasonably practicable but is not responsible for that third party's acts, omissions or performance.</p><p style=\"margin:6px 0;\">Nothing in this Agreement limits any rights available under applicable law.</p>"],
  ["LIABILITY", "<p style=\"margin:6px 0;\">Seventh Sky will perform the agreed Services with reasonable care, skill and professional diligence.</p><p style=\"margin:6px 0;\">The Seller acknowledges that Seventh Sky acts solely as a Commercial Property Sale Service Provider and Coordinator and does not provide legal, financial, taxation, accounting, valuation, engineering, surveying or investment advice.</p><p style=\"margin:6px 0;\">The Seller remains responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">all decisions relating to the sale of the property;</li><li style=\"margin:2px 0;\">confirming legal ownership and authority to sell;</li><li style=\"margin:2px 0;\">providing accurate ownership and property information;</li><li style=\"margin:2px 0;\">obtaining independent professional advice where appropriate; and</li><li style=\"margin:2px 0;\">complying with all legal obligations relating to the property sale.</li></ul><p style=\"margin:6px 0;\">Seventh Sky is not responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">decisions made by the Seller or prospective buyers;</li><li style=\"margin:2px 0;\">acceptance or rejection of offers;</li><li style=\"margin:2px 0;\">changes in market values or sale prices;</li><li style=\"margin:2px 0;\">inaccurate information supplied by the Seller or third parties;</li><li style=\"margin:2px 0;\">the acts or omissions of independent contractors or professional advisers; or</li><li style=\"margin:2px 0;\">professional advice provided by independent third-party professionals.</li></ul>"],
  ["LIMITATION OF LIABILITY", "<p style=\"margin:6px 0;\">To the maximum extent permitted by law, Seventh Sky shall not be liable for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">failure to secure a purchaser;</li><li style=\"margin:2px 0;\">withdrawal of prospective buyers;</li><li style=\"margin:2px 0;\">changes in market value or sale price;</li><li style=\"margin:2px 0;\">delays in negotiations, finance approval, settlement or registration;</li><li style=\"margin:2px 0;\">title defects, ownership disputes or undisclosed encumbrances;</li><li style=\"margin:2px 0;\">inaccurate information supplied by the Seller or third parties;</li><li style=\"margin:2px 0;\">business interruption, loss of opportunity or other indirect or consequential loss; or</li><li style=\"margin:2px 0;\">events beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where liability cannot legally be excluded, Seventh Sky's total liability shall not exceed the Professional Service Fees paid by the Seller for the Services giving rise to the claim.</p><p style=\"margin:6px 0;\">Nothing in this clause excludes liability that cannot legally be excluded under applicable law.</p>"],
  ["CONFIDENTIALITY & PRIVACY", "<p style=\"margin:6px 0;\">Both Parties agree to keep confidential all non-public information obtained through this Agreement.</p><p style=\"margin:6px 0;\">Seventh Sky may collect, use and disclose information only for the purpose of:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">providing the agreed Services;</li><li style=\"margin:2px 0;\">marketing the property;</li><li style=\"margin:2px 0;\">communicating with prospective buyers and authorised third parties;</li><li style=\"margin:2px 0;\">coordinating inspections, negotiations and settlement activities;</li><li style=\"margin:2px 0;\">preparing quotations, reports, invoices and management records;</li><li style=\"margin:2px 0;\">complying with legal obligations; and</li><li style=\"margin:2px 0;\">managing its business operations.</li></ul><p style=\"margin:6px 0;\">Neither Party shall disclose confidential information to any third party without prior consent unless required by law.</p><p style=\"margin:6px 0;\">These obligations continue after completion or termination of this Agreement.</p>"],
  ["FORCE MAJEURE", "<p style=\"margin:6px 0;\">Neither Party shall be liable for delays or failure to perform its obligations where caused by events beyond its reasonable control, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">natural disasters;</li><li style=\"margin:2px 0;\">floods;</li><li style=\"margin:2px 0;\">fire;</li><li style=\"margin:2px 0;\">pandemics;</li><li style=\"margin:2px 0;\">government restrictions;</li><li style=\"margin:2px 0;\">industrial action;</li><li style=\"margin:2px 0;\">utility failures;</li><li style=\"margin:2px 0;\">civil unrest; or</li><li style=\"margin:2px 0;\">other unforeseen events.</li></ul><p style=\"margin:6px 0;\">The affected Party shall notify the other Party as soon as reasonably practicable and resume performance once the event has ended.</p>"],
  ["SELLER ACKNOWLEDGEMENTS", "<p style=\"margin:6px 0;\">The Seller acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">they have read and understood this Agreement;</li><li style=\"margin:2px 0;\">all information provided to Seventh Sky is true, accurate and complete to the best of their knowledge;</li><li style=\"margin:2px 0;\">Seventh Sky provides Commercial Property Sale Services only and is not the purchaser, legal owner or developer of the property;</li><li style=\"margin:2px 0;\">market conditions and buyer demand may affect the sale price and timeframe;</li><li style=\"margin:2px 0;\">the final decision to accept or reject any offer remains solely with the Seller;</li><li style=\"margin:2px 0;\">independent legal, taxation, accounting, valuation, engineering and financial advice should be obtained where appropriate;</li><li style=\"margin:2px 0;\">independent third-party professionals remain responsible for their own advice and services;</li><li style=\"margin:2px 0;\">all agreed Professional Service Fees, commissions, approved expenses and third-party costs remain payable in accordance with this Agreement; and</li><li style=\"margin:2px 0;\">they have had the opportunity to obtain independent legal advice before entering into this Agreement.</li></ul>"],
  ["SUSPENSION & TERMINATION", "<p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.1 Suspension</p><p style=\"margin:6px 0;\">Seventh Sky may suspend all or part of the Services where the Seller:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">fails to pay any outstanding amount in accordance with this Agreement;</li><li style=\"margin:2px 0;\">provides false, misleading or incomplete information;</li><li style=\"margin:2px 0;\">fails to provide information or cooperation reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">requests Seventh Sky to undertake any unlawful activity; or</li><li style=\"margin:2px 0;\">commits a material breach of this Agreement.</li></ul><p style=\"margin:6px 0;\">Where reasonably practicable, Seventh Sky will notify the Seller before suspending the Services.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.2 Termination</p><p style=\"margin:6px 0;\">Either Party may terminate this Agreement by providing written notice to the other Party.</p><p style=\"margin:6px 0;\">Seventh Sky may terminate this Agreement immediately where the Seller:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commits a material breach of this Agreement;</li><li style=\"margin:2px 0;\">repeatedly fails to pay agreed Professional Service Fees;</li><li style=\"margin:2px 0;\">engages in fraudulent or unlawful conduct;</li><li style=\"margin:2px 0;\">intentionally circumvents Seventh Sky in breach of this Agreement; or</li><li style=\"margin:2px 0;\">otherwise acts in a manner that makes continuation of the Services unreasonable.</li></ul><p style=\"margin:6px 0;\">Upon termination:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Professional Service Fees for Services already completed remain payable;</li><li style=\"margin:2px 0;\">approved marketing costs and third-party expenses remain payable;</li><li style=\"margin:2px 0;\">obligations intended to survive termination shall continue; and</li><li style=\"margin:2px 0;\">termination does not affect any rights or obligations accrued before the termination date.</li></ul>"],
  ["NON-CIRCUMVENTION", "<p style=\"margin:6px 0;\">The Seller acknowledges that Seventh Sky invests considerable time, expertise and commercial resources in marketing commercial properties, sourcing prospective buyers, coordinating inspections, facilitating negotiations and supporting successful property sales.</p><p style=\"margin:6px 0;\">Accordingly, where Seventh Sky introduces a prospective buyer, investor or authorised representative, the Seller agrees not to intentionally bypass Seventh Sky to avoid payment of the agreed Professional Service Fees or commission.</p><p style=\"margin:6px 0;\">This obligation applies during the term of this Agreement and for twelve (12) months following the relevant introduction.</p><p style=\"margin:6px 0;\">This clause does not prevent the Seller from selling the property to a purchaser who was not introduced by Seventh Sky.</p>"],
  ["GENERAL PROVISIONS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">this Agreement, together with the accepted Quotation, Work Order and Schedules, constitutes the entire agreement between the Parties;</li><li style=\"margin:2px 0;\">any amendment to this Agreement must be made in writing and accepted by both Parties;</li><li style=\"margin:2px 0;\">failure by either Party to enforce any provision shall not constitute a waiver of that provision;</li><li style=\"margin:2px 0;\">if any provision is found to be invalid or unenforceable, the remaining provisions shall remain in full force and effect; and</li><li style=\"margin:2px 0;\">notices under this Agreement may be delivered by hand, registered post, courier or email.</li></ul>"],
  ["GOVERNING LAW", "<p style=\"margin:6px 0;\">This Agreement shall be governed by the laws of the People's Republic of Bangladesh.</p><p style=\"margin:6px 0;\">The Parties agree to use reasonable efforts to resolve any dispute through good faith discussions before commencing legal proceedings.</p><p style=\"margin:6px 0;\">Where a dispute cannot be resolved through negotiation, either Party may refer the matter to the competent courts of Bangladesh.</p>"],
  ["EXECUTION", "<p style=\"margin:6px 0;\">By signing this Agreement, the Parties confirm that they:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">have read and understood this Agreement;</li><li style=\"margin:2px 0;\">have had the opportunity to obtain independent legal advice;</li><li style=\"margin:2px 0;\">agree to be bound by the terms of this Agreement; and</li><li style=\"margin:2px 0;\">enter into this Agreement voluntarily.</li></ul><p style=\"margin:6px 0;\">This Agreement may be executed in counterparts and by electronic signature, each of which shall be deemed an original.</p>"],
];
